CREATE OR REPLACE FUNCTION public.apply_seller_shipping_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  handling_days smallint;
  shipping_method text;
BEGIN
  IF coalesce(auth.role(),'')='service_role'
     AND EXISTS(SELECT 1 FROM public.managed_import_sellers WHERE owner_user_id=NEW.seller_id)
     AND current_setting('parkvault.trusted_operation',true)='on' THEN
    NEW.ship_by_days:=coalesce(NEW.ship_by_days,7);
    RETURN NEW;
  END IF;

  IF NEW.in_hand AND NOT NEW.is_demo THEN
    SELECT sp.default_handling_days, sp.default_shipping_method
      INTO handling_days, shipping_method
      FROM public.seller_profiles sp
     WHERE sp.user_id = NEW.seller_id AND sp.status = 'active';
    IF handling_days IS NULL OR shipping_method IS NULL THEN
      RAISE EXCEPTION 'Choose shipping method and handling time in your seller profile before listing';
    END IF;
    NEW.ship_by_days := handling_days;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.bind_import_seller_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s public.managed_import_sellers; BEGIN
 SELECT * INTO s FROM public.managed_import_sellers WHERE source_profile_url=NEW.source_profile_url FOR UPDATE;
 IF s.id IS NOT NULL THEN
  IF s.claimed_at IS NULL AND EXISTS(SELECT 1 FROM public.seller_claim_transfers j JOIN public.seller_claim_tokens t ON t.id=j.claim_token_id WHERE t.managed_seller_id=s.id AND j.status='preparing' AND j.lease_until>now()) THEN RAISE EXCEPTION 'Claim in progress; retry importing after it finishes'; END IF;
  NEW.seller_id:=s.owner_user_id;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.cancel_ask(_ask_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

DECLARE uid uuid := auth.uid(); a record;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  PERFORM set_config('parkvault.trusted_operation', 'on', true);
  SELECT * INTO a FROM public.asks WHERE id = _ask_id AND seller_id = uid FOR UPDATE;
  IF a.id IS NULL THEN RAISE EXCEPTION 'Ask not found'; END IF;
  IF a.status <> 'active' THEN RAISE EXCEPTION 'Only active Asks can be cancelled'; END IF;
  UPDATE public.asks SET status = 'cancelled' WHERE id = _ask_id;
  INSERT INTO public.ask_events (ask_id, actor_id, event_type, from_status, to_status)
  VALUES (_ask_id, uid, 'cancelled', 'active', 'cancelled');
  PERFORM set_config('parkvault.trusted_operation', 'off', true);
END;
END;$function$

