CREATE OR REPLACE FUNCTION public.guard_archived_import_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ BEGIN
 -- Claim transfer may still update only ownership and photo paths on a removed source.
 IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('fb_marketplace_import_items','fb_marketplace_import_batches') THEN
   IF (to_jsonb(NEW) - ARRAY['seller_id','evidence_paths','public_paths','updated_at']) IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['seller_id','evidence_paths','public_paths','updated_at']) THEN RETURN NEW; END IF;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.source_profile_url,0));
 IF EXISTS(SELECT 1 FROM public.import_source_archives WHERE source_profile_url=NEW.source_profile_url AND archived_at IS NOT NULL)
 THEN RAISE EXCEPTION 'This import was removed. Restore it before importing or refreshing'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_ask_user_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF public.is_trusted_operation() THEN RETURN NEW; END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in required';
  END IF;
  IF auth.uid() <> OLD.seller_id OR auth.uid() <> NEW.seller_id THEN
    RAISE EXCEPTION 'Only the Ask owner may change this Ask';
  END IF;

  IF NEW.product_id <> OLD.product_id
     OR NEW.variant_id <> OLD.variant_id
     OR NEW.currency <> OLD.currency
     OR NEW.is_demo <> OLD.is_demo
     OR NEW.in_hand <> OLD.in_hand
     OR NEW.evidence_count <> OLD.evidence_count
     OR COALESCE(NEW.matched_order_id::text, '') <> COALESCE(OLD.matched_order_id::text, '') THEN
    RAISE EXCEPTION 'This field on an Ask is not member-editable';
  END IF;
  IF NEW.status NOT IN ('active', 'cancelled') THEN
    RAISE EXCEPTION 'Members may only cancel an Ask';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_market_interest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE recipient uuid; product_name text;
BEGIN
  IF NEW.is_demo OR NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'asks' AND NEW.approved_at IS NULL THEN RETURN NEW; END IF;
  SELECT name INTO product_name FROM public.products WHERE id = NEW.product_id;
  IF TG_TABLE_NAME = 'bids' THEN
    FOR recipient IN
      SELECT DISTINCT seller_id FROM public.asks
      WHERE variant_id = NEW.variant_id AND status = 'active' AND approved_at IS NOT NULL
        AND expires_at > now() AND seller_id <> NEW.buyer_id
    LOOP
      PERFORM public.notify_member(recipient, 'new_bid', 'New Bid on ' || product_name,
        'A buyer placed a ' || to_char(NEW.price_cents / 100.0, 'FM$999G999G990D00') ||
        ' Bid. Accept it or edit your Ask to counter.', NULL);
    END LOOP;
  ELSE
    FOR recipient IN
      SELECT DISTINCT buyer_id FROM public.bids
      WHERE variant_id = NEW.variant_id AND status = 'active' AND expires_at > now()
        AND buyer_id <> NEW.seller_id
    LOOP
      PERFORM public.notify_member(recipient, 'new_ask', 'New Ask for ' || product_name,
        'A seller listed this item for ' || to_char(NEW.price_cents / 100.0, 'FM$999G999G990D00') || '.', NULL);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_classified_product_after_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status = 'active'
     AND NEW.approved_at IS NOT NULL
     AND NOT NEW.is_demo
     AND EXISTS (
       SELECT 1
       FROM public.classified_listing_details AS details
       WHERE details.listing_id = NEW.id
     ) THEN
    PERFORM set_config('parkvault.trusted_operation', 'on', true);

    UPDATE public.products
    SET status = 'published'::public.product_status
    WHERE id = NEW.product_id
      AND status = 'pending_review'::public.product_status;

    PERFORM set_config('parkvault.trusted_operation', 'off', true);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('parkvault.trusted_operation', 'off', true);
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.relist_ask(_ask_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

DECLARE uid uuid := auth.uid(); old_status public.listing_status;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  SELECT status INTO old_status FROM public.asks
    WHERE id = _ask_id AND seller_id = uid FOR UPDATE;
  IF old_status IS NULL THEN RAISE EXCEPTION 'Ask not found'; END IF;
  IF old_status NOT IN ('cancelled','expired') THEN RAISE EXCEPTION 'Only a cancelled or expired Ask can be relisted'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ask_media WHERE ask_id = _ask_id)
     OR NOT EXISTS (SELECT 1 FROM public.listing_media WHERE ask_id = _ask_id) THEN
    RAISE EXCEPTION 'Private evidence and a public listing photo are required';
  END IF;
  UPDATE public.asks SET status = 'active', approved_at = NULL, approved_by = NULL,
    review_note = NULL, expires_at = now() + interval '30 days',
    matched_order_id = NULL, updated_at = now() WHERE id = _ask_id;
  INSERT INTO public.ask_events (ask_id, actor_id, event_type, from_status, to_status, price_cents, note)
  SELECT id, uid, 'released', old_status, 'active', price_cents, 'Relisted by seller; awaiting admin approval'
  FROM public.asks WHERE id = _ask_id;
END;
END;$function$

