CREATE OR REPLACE FUNCTION public.replace_listing_media(_ask_id uuid, _paths text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

DECLARE uid uuid := auth.uid(); p text; idx integer := 0;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  IF coalesce(array_length(_paths,1),0) < 1 OR coalesce(array_length(_paths,1),0) > 8 THEN
    RAISE EXCEPTION 'Add between 1 and 8 listing photos';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.asks WHERE id = _ask_id AND seller_id = uid AND status = 'active') THEN
    RAISE EXCEPTION 'Only an open Ask can be edited';
  END IF;
  DELETE FROM public.listing_media WHERE ask_id = _ask_id;
  FOREACH p IN ARRAY _paths LOOP
    IF split_part(p,'/',1) <> uid::text THEN RAISE EXCEPTION 'Listing photo path does not belong to the caller'; END IF;
    INSERT INTO public.listing_media (ask_id, storage_path, position, rights_attested_at)
    VALUES (_ask_id, p, idx, now());
    idx := idx + 1;
  END LOOP;
  UPDATE public.asks SET approved_at = NULL, approved_by = NULL, review_note = NULL,
    updated_at = now() WHERE id = _ask_id;
END;
END;$function$

