CREATE OR REPLACE FUNCTION public.require_verified_seller_for_ask()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  uid uuid := auth.uid();
  seller public.seller_profiles;
BEGIN
  IF uid IS NULL OR NEW.seller_id <> uid THEN
    RETURN NEW;
  END IF;
  SELECT * INTO seller FROM public.seller_profiles WHERE user_id = uid;
  IF seller.user_id IS NULL OR seller.status <> 'active' OR seller.terms_accepted_at IS NULL THEN
    RAISE EXCEPTION 'Complete seller setup before listing';
  END IF;
  RETURN NEW;
END
