CREATE OR REPLACE FUNCTION public.update_ask(_ask_id uuid, _price_cents integer, _item_condition item_condition, _seller_note text, _parcel_length_in numeric, _parcel_width_in numeric, _parcel_height_in numeric, _parcel_weight_lb numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

DECLARE uid uuid := auth.uid(); old_price integer; was_approved boolean;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  IF _price_cents < 100 OR _price_cents > 1000000000 THEN RAISE EXCEPTION 'Ask price out of range'; END IF;
  SELECT price_cents, approved_at IS NOT NULL INTO old_price, was_approved FROM public.asks
    WHERE id = _ask_id AND seller_id = uid AND status = 'active' FOR UPDATE;
  IF old_price IS NULL THEN RAISE EXCEPTION 'Only an open Ask can be edited'; END IF;
  UPDATE public.asks SET price_cents = _price_cents, item_condition = _item_condition,
    seller_note = nullif(btrim(_seller_note),''), parcel_length_in = _parcel_length_in,
    parcel_width_in = _parcel_width_in, parcel_height_in = _parcel_height_in,
    parcel_weight_lb = _parcel_weight_lb, approved_at = NULL, approved_by = NULL,
    review_note = NULL, updated_at = now()
    WHERE id = _ask_id;
  IF old_price <> _price_cents OR was_approved THEN
    INSERT INTO public.ask_events (ask_id, actor_id, event_type, price_cents, note)
    VALUES (_ask_id, uid, 'price_changed', _price_cents,
      CASE WHEN was_approved THEN 'Listing updated by seller and returned to admin review'
           ELSE 'Listing updated by seller while awaiting review' END);
  END IF;
END;
END;$function$

